test_that("planning finds gaps and overlap", { d<-data.frame(valid=TRUE,estimated=FALSE,date=as.Date(c("2026-01-01","2026-01-03"))); p<-plan_observed_update(d,"2026-01-01","2026-01-04",1); expect_true(as.Date("2026-01-02")%in%p$date); expect_true(as.Date("2026-01-04")%in%p$date); expect_equal(nrow(compress_dates_to_intervals(p$date)),1) })
test_that("safe date sequence handles reversed and invalid boundaries", { expect_equal(safe_date_sequence("2026-07-01","2026-07-03"),as.Date(c("2026-07-01","2026-07-02","2026-07-03"))); expect_length(safe_date_sequence("2026-07-04","2026-07-03"),0); expect_error(safe_date_sequence(c("2026-07-01","2026-07-02"),"2026-07-03"),"scalar"); expect_error(safe_date_sequence(NA,"2026-07-03"),"valid") })
test_that("complete existing smoke coverage produces an empty no-op plan", { d<-data.frame(valid=TRUE,estimated=FALSE,date=as.Date(c("2026-07-03","2026-07-01","2026-07-02","2026-07-02"))); p<-plan_observed_update(d,"2026-07-01","2026-07-03",0); expect_length(p$date,0); expect_equal(attr(p,"status"),"success_noop"); expect_equal(attr(p,"reason"),"no_missing_dates") })
